namespace DMM.AssetManagers.NIF;
internal static class NifSchemaCommon { public static void Add(List<NifSchemaType> t) { t.Add(new("NiObject", false, null, new AnyPredicate(), [])); t.Add(new("NiObjectNET", false, "NiObject", new AnyPredicate(), [new("Name", NifFieldKind.StringIndex), new("Num Extra Data List", NifFieldKind.UInt32), new("Extra Data List", NifFieldKind.Array, Template:"NiExtraData", Length:new CountField("Num Extra Data List")), new("Controller", NifFieldKind.Ref, Template:"NiTimeController")])); t.Add(new("NiExtraData", false, "NiObject", new AnyPredicate(), [new("Name", NifFieldKind.StringIndex)])); } }
internal static class NifSchemaBethesda { public static void Add(List<NifSchemaType> t) { t.Add(new("BSShaderProperty", false, "NiObjectNET", new AnyPredicate(), [])); t.Add(new("BSBehaviorGraphExtraData", false, "NiExtraData", new AnyPredicate(), [new("Behaviour Graph File", NifFieldKind.StringIndex, DependencyCategory:"Behavior", Normalization:NifNormalizationStrategy.Behavior), new("Controls Base Skeleton", NifFieldKind.Bool)])); } }
internal static class NifSchemaSkyrim { public static void Add(List<NifSchemaType> t) { var p=new FamilyPredicate(NifFamily.Skyrim,83); t.Add(new("BSShaderTextureSet", false, "NiObject", p, [new("Textures", NifFieldKind.Array, Template:"SizedString", Length:new CountField("Num Textures"), DependencyCategory:"Texture", Normalization:NifNormalizationStrategy.Texture)])); } }
internal static class NifSchemaFallout4 { public static void Add(List<NifSchemaType> t) { var p=new FamilyPredicate(NifFamily.Fallout4,130,169); t.Add(new("BSTriShape", false, "NiObjectNET", p, [])); t.Add(new("BSLightingShaderProperty", false, "BSShaderProperty", p, [new("Material", NifFieldKind.StringIndex, DependencyCategory:"Material", Normalization:NifNormalizationStrategy.Material)])); t.Add(new("BSEffectShaderProperty", false, "BSShaderProperty", p, [new("Material", NifFieldKind.StringIndex, DependencyCategory:"Material", Normalization:NifNormalizationStrategy.Material)])); } }
internal static class NifSchemaStarfield { public static void Add(List<NifSchemaType> t) { var p=new FamilyPredicate(NifFamily.Starfield,170); t.Add(new("BSMesh", true, null, p, [new("Indices Size", NifFieldKind.UInt32),new("Num Verts",NifFieldKind.UInt32),new("Flags",NifFieldKind.UInt32),new("Mesh Path",NifFieldKind.SizedString, Length:new BitFlagLength("Flags",512),DependencyCategory:"Mesh",Normalization:NifNormalizationStrategy.Mesh)])); t.Add(new("BSGeometry", false, "NiObjectNET", p, [new("Meshes",NifFieldKind.Array,Template:"BSMesh",Length:new FixedLength(4))])); foreach(var n in new[]{"BSLightingShaderProperty","BSEffectShaderProperty"}) t.Add(new(n,false,"BSShaderProperty",p,[new("Material",NifFieldKind.StringIndex,DependencyCategory:"Material",Normalization:NifNormalizationStrategy.Material)])); t.Add(new("SkinAttach",false,"NiExtraData",p,[])); t.Add(new("BoneTranslations",false,"NiExtraData",p,[])); t.Add(new("BSWeakReferenceNode",false,"NiObjectNET",p,[])); } }
internal static class NifSchemaLegacy { public static void Add(List<NifSchemaType> t) { t.Add(new("NiSourceTexture",false,"NiObjectNET",new FamilyPredicate(NifFamily.Other),[new("File Name",NifFieldKind.SizedString,DependencyCategory:"Texture",Normalization:NifNormalizationStrategy.Texture)])); } }
